[CmdletBinding()]
param([Parameter(Mandatory)][string]$InputPath, [string]$OutputPath = 'performance/reports/r9-summary.json')
$ErrorActionPreference='Stop'; $validator=Join-Path $PSScriptRoot 'Validate-R9Jsonl.ps1'
function P([double[]]$a,[double]$q){$s=$a|Sort-Object;$i=($s.Count-1)*$q;$lo=[math]::Floor($i);$hi=[math]::Ceiling($i);if($lo -eq $hi){return [double]$s[$lo]};return [double]$s[$lo]+($s[$hi]-$s[$lo])*($i-$lo)}
$files=@(Get-ChildItem -LiteralPath $InputPath -Filter '*.jsonl' -File -Recurse);if(!$files){throw "No JSONL runs found"};$all=@();foreach($f in $files){& $validator -Path $f.FullName | Out-Null; $all += @(Get-Content -LiteralPath $f.FullName | ?{$_} | % {$_|ConvertFrom-Json})}
$groups=$all|Group-Object sceneId; $rows=@(); foreach($g in $groups){$x=$g.Group; $checks=@($x|% checksum|Select-Object -Unique);if($checks.Count -ne 1){throw "Checksum parity failure for scene $($g.Name)"};$frame=@($x|% frameTimeMs|% {[double]$_});$cpu=@($x|% cpuMs|% {[double]$_});$p95=P $frame .95;$p99=P $frame .99;$rows += [ordered]@{sceneId=$g.Name;frames=$x.Count;checksum=$checks[0];cpuP50Ms=(P $cpu .5);cpuP95Ms=(P $cpu .95);cpuP99Ms=(P $cpu .99);frameP50Ms=(P $frame .5);frameP95Ms=$p95;frameP99Ms=$p99;onePercentLowFps=(1000/$p99);workingSetP50Bytes=(P @($x|% workingSetBytes|% {[double]$_}) .5);uploadP50Bytes=(P @($x|% uploadBytes|% {[double]$_}) .5);drawP50=(P @($x|% drawCalls|% {[double]$_}) .5);bufferP50Bytes=(P @($x|% bufferBytes|% {[double]$_}) .5);queueDepthP95=(P @($x|% queueDepth|% {[double]$_}) .95);queueDelayP95Ms=(P @($x|% queueDelayMs|% {[double]$_}) .95)}}
$out=[ordered]@{schema='icraft.r9.summary.v1';generatedUtc=[DateTime]::UtcNow.ToString('o');scenes=$rows};$par=Split-Path -Parent $OutputPath;if($par){New-Item -ItemType Directory -Force $par|Out-Null};$out|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 -LiteralPath $OutputPath;Write-Output (Resolve-Path $OutputPath)
